import { spawnSync } from 'node:child_process';

const bin = '/workspace/dataset/test2_executable';
const cases = [
  ['missing_required', []],
  ['help', ['--help']],
  ['equals_form', ['--a=foo']],
  ['duplicate_a', ['--a', 'first', '--a', 'second']],
  ['unknown_before', ['--unknown', 'x', '--a', 'foo']],
  ['unknown_after', ['--a', 'foo', '--unknown', 'x']],
