  ['dash_value_after_double_dash', ['--a', '--', 'foo']],
  ['help_with_unknown', ['--help', '--unknown']],
];

for (const [name, args] of cases) {
  const result = spawnSync(bin, args, { encoding: 'utf8' });
  const rc = result.status ?? (result.signal ? `signal:${result.signal}` : 'null');
  console.log(`CASE=${name}`);
  console.log(`ARGS=${JSON.stringify(args)}`);
  console.log(`RC=${rc}`);
  console.log('STDOUT_BEGIN');
  process.stdout.write(result.stdout || '');
  if (!(result.stdout || '').endsWith('\n')) console.log();
  console.log('STDOUT_END');
  console.log('STDERR_BEGIN');
  process.stdout.write(result.stderr || '');
  if (!(result.stderr || '').endsWith('\n')) console.log();
  console.log('STDERR_END');
}
